Future<void> _configure(faui.AddProviderPreset preset) async {
  final registry = _beginPresetFlow(preset);
  if (registry == null) return;
  var ok = false;
  try {
    ok = await _runPresetFlow(preset, registry);
  } on Object catch (e) {
    _showFlowError(e);
  } finally {
    _endPresetFlow(preset.key);
  }
